CREATE TABLE public.satellite_pilot_day_selection(vineyard_id uuid NOT NULL,paddock_id uuid NOT NULL,acquisition_day date NOT NULL,acquisition_id uuid NOT NULL REFERENCES public.satellite_acquisitions(id),boundary_hash text NOT NULL,PRIMARY KEY(vineyard_id,paddock_id,acquisition_day),CHECK(vineyard_id='fe952afe-437f-4be7-8cbf-fdd8e630411c'::uuid));
GRANT ALL ON public.satellite_pilot_day_selection TO service_role;
REVOKE ALL ON public.satellite_pilot_day_selection FROM PUBLIC,anon,authenticated;
ALTER TABLE public.satellite_pilot_day_selection ENABLE ROW LEVEL SECURITY;
CREATE POLICY service_only ON public.satellite_pilot_day_selection TO service_role USING(true) WITH CHECK(true);
CREATE FUNCTION public.satellite_enqueue_pilot(p_acquisition uuid,p_paddock uuid,p_boundary jsonb,p_hash text) RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public.satellite_acquisitions; chosen uuid; n integer; BEGIN SELECT * INTO STRICT a FROM public.satellite_acquisitions WHERE id=p_acquisition; IF NOT public.satellite_pipeline_enabled('fe952afe-437f-4be7-8cbf-fdd8e630411c',a.provider,false) THEN RETURN 0; END IF; IF p_hash !~ '^[a-f0-9]{64}$' OR jsonb_typeof(p_boundary)<>'array' THEN RAISE EXCEPTION 'Invalid boundary'; END IF; INSERT INTO public.satellite_pilot_day_selection VALUES('fe952afe-437f-4be7-8cbf-fdd8e630411c',p_paddock,(a.acquired_at AT TIME ZONE 'UTC')::date,a.id,p_hash) ON CONFLICT DO NOTHING; SELECT acquisition_id INTO chosen FROM public.satellite_pilot_day_selection WHERE vineyard_id='fe952afe-437f-4be7-8cbf-fdd8e630411c' AND paddock_id=p_paddock AND acquisition_day=(a.acquired_at AT TIME ZONE 'UTC')::date; IF chosen<>a.id THEN RETURN 0; END IF; INSERT INTO public.satellite_work_items(vineyard_id,paddock_id,acquisition_id,layer,boundary_snapshot,boundary_hash) SELECT 'fe952afe-437f-4be7-8cbf-fdd8e630411c',p_paddock,a.id,l,p_boundary,p_hash FROM unnest(ARRAY['NDVI','TRUE_COLOUR']) l ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.satellite_enqueue_pilot(uuid,uuid,jsonb,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.satellite_enqueue_pilot(uuid,uuid,jsonb,text) TO service_role;